<?php require __DIR__.'/../includes/bootstrap.php'; require_admin(); $error=''; $edit=['id'=>0,'name'=>'','slug'=>'','description'=>'']; if($pdo&&isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM categories WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch()?:$edit;} if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';$id=(int)($_POST['id']??0);if($action==='delete'&&$id&&$pdo){$pdo->prepare('DELETE FROM categories WHERE id=?')->execute([$id]);header('Location: categories.php');exit;}if($action==='save'){$name=trim($_POST['name']??'');$slug=trim($_POST['slug']??'');$desc=trim($_POST['description']??'');if($name===''||!preg_match('/^[a-z0-9]+(?:-[a-z0-9]+)*$/',$slug))$error='Enter a name and a valid lowercase slug.';elseif($pdo){try{if($id)$pdo->prepare('UPDATE categories SET name=?,slug=?,description=? WHERE id=?')->execute([$name,$slug,$desc,$id]);else $pdo->prepare('INSERT INTO categories(name,slug,description) VALUES(?,?,?)')->execute([$name,$slug,$desc]);header('Location: categories.php');exit;}catch(PDOException $e){$error='Unable to save category; the slug may already exist.';}}}}$cats=$pdo?$pdo->query('SELECT * FROM categories ORDER BY name')->fetchAll():[];?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Categories</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><header><a class="brand" href="dashboard.php">ASMR Audio Admin</a><nav><a href="articles.php">Articles</a><a href="categories.php">Categories</a><a href="logout.php">Log out</a></nav></header><main class="container"><h1>Categories</h1><?php if($error):?><p role="alert"><?=e($error)?></p><?php endif;?><form method="post" class="card"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=$edit['id']?>"><p><label>Name<input name="name" value="<?=e($edit['name'])?>" required></label></p><p><label>Slug<input name="slug" value="<?=e($edit['slug'])?>" required></label></p><p><label>Description<textarea name="description"><?=e($edit['description']??'')?></textarea></label></p><button>Save category</button><?php if($edit['id']):?> <a href="categories.php">Cancel</a><?php endif;?></form><section class="card"><table style="width:100%"><tr><th>Name</th><th>Slug</th><th>Actions</th></tr><?php foreach($cats as $c):?><tr><td><?=e($c['name'])?></td><td><?=e($c['slug'])?></td><td><a href="?edit=<?=$c['id']?>">Edit</a> <form method="post" style="display:inline"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$c['id']?>"><button type="submit">Delete</button></form></td></tr><?php endforeach;?></table></section></main></body></html>
